from __future__ import annotations

import json
import os

from starlette.responses import HTMLResponse


def dashboard_enabled() -> bool:
    value = os.getenv("SMART_ROUTER_DASHBOARD_ENABLED", "true")
    return value.strip().lower() in {"1", "true", "yes", "on"}


def dashboard_response(*, version: str) -> HTMLResponse:
    safe_version = json.dumps(str(version))
    return HTMLResponse(
        _TEMPLATE.replace("__HERMES_VERSION_JSON__", safe_version),
        headers={"Cache-Control": "no-store"},
    )


_TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark light">
<title>Hermes Flight Deck · Smart Router</title>
<style>
:root{--bg:#070a12;--surface:#0d1220;--surface2:#121a2c;--surface3:#182238;--line:#26344f;--text:#f2f6ff;--muted:#93a3bd;--cyan:#62e6ff;--violet:#8b7cff;--green:#64e6ad;--amber:#ffc86b;--red:#ff7887;--sidebar:rgba(7,10,18,.94);--canvas:#0d1220;--shadow:0 24px 70px rgba(0,0,0,.28);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:dark}[data-theme="light"]{--bg:#f4f7fb;--surface:#fff;--surface2:#f7f9fc;--surface3:#eaf0f8;--line:#d6deea;--text:#132033;--muted:#66758b;--cyan:#087e9a;--violet:#6555d9;--green:#16855d;--amber:#9b6a12;--red:#c53d4c;--sidebar:#fff;--canvas:#fff;--shadow:0 16px 42px rgba(34,53,78,.10);color-scheme:light}*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;color:var(--text);background:radial-gradient(900px 600px at 15% -10%,rgba(98,230,255,.10),transparent 60%),radial-gradient(800px 650px at 100% 0,rgba(139,124,255,.12),transparent 55%),var(--bg);min-height:100vh}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.22;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:32px 32px}.shell{display:grid;grid-template-columns:238px 1fr;min-height:100vh}.side{position:sticky;top:0;height:100vh;border-right:1px solid var(--line);padding:24px 18px;background:var(--sidebar)}.brand{display:flex;align-items:center;gap:12px;font-weight:850;letter-spacing:-.02em}.mark{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(98,230,255,.18),rgba(139,124,255,.20));border:1px solid rgba(98,230,255,.28);box-shadow:inset 0 0 24px rgba(98,230,255,.08)}.mark svg{width:24px;height:24px}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;margin-top:2px}.nav{margin-top:30px}.navlabel{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.13em;margin:18px 10px 7px}.nav a{display:flex;gap:10px;align-items:center;color:var(--muted);text-decoration:none;padding:10px 11px;border-radius:10px;font-size:14px;margin:3px 0;border:1px solid transparent}.nav a.active{background:linear-gradient(90deg,rgba(98,230,255,.12),rgba(139,124,255,.08));color:var(--text);border-color:rgba(98,230,255,.24)}.nav a:hover{background:var(--surface2);color:var(--text)}.sidefoot{position:absolute;bottom:22px;left:18px;right:18px;color:var(--muted);font-size:12px;line-height:1.5}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green);margin-right:7px}.main{min-width:0;padding:26px clamp(18px,3vw,42px) 48px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:26px}.eyebrow{font-size:11px;color:var(--cyan);text-transform:uppercase;letter-spacing:.16em;font-weight:800}.top h1{margin:4px 0 0;font-size:clamp(26px,3vw,38px);letter-spacing:-.04em}.top-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.control,button,select,input{font:inherit}button,select,input{border:1px solid var(--line);background:var(--surface2);color:var(--text);border-radius:10px;padding:9px 11px}button{cursor:pointer}.primary{border-color:rgba(98,230,255,.35);background:linear-gradient(135deg,rgba(98,230,255,.16),rgba(139,124,255,.14))}.ghost:hover,button:hover{border-color:var(--cyan)}.statuspill{display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:var(--surface);font-size:12px;color:var(--muted)}.authbox{display:none;position:absolute;right:42px;top:78px;z-index:20;width:min(430px,calc(100vw - 36px));padding:16px;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}.authbox.open{display:block}.authbox h3{margin:0 0 5px;font-size:15px}.authbox p{margin:0 0 12px;color:var(--muted);font-size:12px;line-height:1.5}.authrow{display:flex;gap:8px}.authrow input{min-width:0;flex:1}.hero{display:grid;grid-template-columns:1.45fr .75fr;gap:14px;margin-bottom:14px}.card{background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:inset 0 1px rgba(255,255,255,.025)}.routehero{padding:22px;position:relative;overflow:hidden}.routehero:after{content:"";position:absolute;width:250px;height:250px;border-radius:50%;right:-90px;top:-120px;background:radial-gradient(circle,rgba(98,230,255,.12),transparent 68%)}.routehero h2{margin:0;font-size:19px}.routehero p{margin:7px 0 18px;color:var(--muted);font-size:13px;max-width:650px;line-height:1.55}.flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.node{padding:9px 12px;border-radius:10px;background:var(--surface2);border:1px solid var(--line);font-size:12px;font-weight:700}.node.auto{border-color:rgba(98,230,255,.35);color:var(--cyan)}.arrow{color:#586a88}.tiers{display:flex;gap:7px;flex-wrap:wrap}.tier{padding:8px 10px;border-radius:999px;background:var(--surface2);border:1px solid var(--line);font-size:11px}.quality{padding:22px}.quality .qtop{display:flex;justify-content:space-between;align-items:center}.score{font-size:30px;font-weight:850;letter-spacing:-.04em;margin-top:16px}.muted{color:var(--muted)}.small{font-size:12px;line-height:1.5}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric{padding:16px;min-height:120px}.metric .label{color:#8698b5;font-size:10px;letter-spacing:.12em;text-transform:uppercase;font-weight:800}.metric .value{font-size:26px;font-weight:850;letter-spacing:-.035em;margin-top:12px}.metric .sub{font-size:11px;color:var(--muted);margin-top:8px;line-height:1.45}.metric.accent .value{color:var(--cyan)}.lower{display:grid;grid-template-columns:1.15fr .85fr;gap:12px;margin-top:12px}.panel{padding:18px}.panelhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.panel h3{margin:0;font-size:14px}.barrow{display:grid;grid-template-columns:88px 1fr 62px;gap:10px;align-items:center;margin:13px 0;font-size:12px}.track{height:9px;border-radius:99px;background:var(--surface3);overflow:hidden}.fill{height:100%;border-radius:99px;background:linear-gradient(90deg,var(--cyan),var(--violet))}.notice{padding:13px;border:1px solid var(--line);background:var(--surface2);border-radius:11px;font-size:12px;line-height:1.55;color:var(--text)}.notice.warn{border-color:color-mix(in srgb,var(--amber) 45%,var(--line));background:color-mix(in srgb,var(--amber) 8%,var(--surface));color:var(--text)}.zero{display:none;margin-top:12px;padding:16px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);font-size:12px;line-height:1.55}.zero.show{display:block}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:var(--surface2);border:1px solid var(--line);padding:8px 10px;border-radius:8px;display:block;margin-top:9px;overflow:auto;color:var(--text)}.legend{display:flex;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin-top:13px}.legend b{color:var(--text)}.trace-list{max-height:360px;overflow:auto}.trace-row{padding:10px;border-bottom:1px solid var(--line);cursor:pointer}.trace-row:hover{background:var(--surface2)}.trace-stage{font-weight:750}.flash{animation:flash .5s ease}@keyframes flash{0%{opacity:.4}100%{opacity:1}}@media(max-width:1050px){.metrics{grid-template-columns:repeat(2,1fr)}.hero,.lower{grid-template-columns:1fr}}@media(max-width:760px){.shell{display:block}.side{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--line);padding:14px 16px}.brand{margin-bottom:10px}.nav{display:flex;gap:6px;margin:0;overflow:auto}.navlabel,.sidefoot{display:none}.nav a{white-space:nowrap}.main{padding:20px 15px 40px}.top{align-items:flex-start}.authbox{right:15px;top:134px}.metrics{grid-template-columns:1fr}.flow{align-items:flex-start;flex-direction:column}.arrow{transform:rotate(90deg);margin-left:15px}}
</style>
</head>
<body>
<div class="shell">
  <aside class="side">
    <div class="brand"><div class="mark"><svg viewBox="0 0 24 24" fill="none"><path d="M4 12h5l3-7 3 14 2-7h3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div>Hermes Router<small>Flight Deck · v<span class="ver"></span></small></div></div>
    <div class="nav"><div class="navlabel">Observe</div><a class="active" href="/dashboard">◈ Flight Deck</a><div class="navlabel">Operate</div><a href="/control/">⌘ Operations Center</a><div class="navlabel">API</div><a href="/v1/models">↗ Models endpoint</a></div>
    <div class="sidefoot"><span class="dot"></span>Smart Router online<br>Telemetry stays on this deployment.</div>
  </aside>
  <main class="main">
    <div class="top">
      <div><div class="eyebrow">Measured routing telemetry</div><h1>Flight Deck</h1></div>
      <div class="top-actions">
        <div class="statuspill"><span class="dot" id="authDot"></span><span id="authState">Checking access</span></div>
        <select id="hours" aria-label="Telemetry time window"><option value="1">Last hour</option><option value="24" selected>Last 24 hours</option><option value="168">Last 7 days</option><option value="720">Last 30 days</option></select>
        <select id="autoRefresh" aria-label="Auto refresh"><option value="0">Auto refresh off</option><option value="15">Every 15 sec</option><option value="30" selected>Every 30 sec</option><option value="60">Every minute</option></select>
        <button class="ghost" id="theme">Theme</button><button class="ghost" id="refresh">Refresh</button><button class="primary" id="authBtn">Access key</button>
      </div>
    </div>
    <div class="authbox" id="authBox"><h3>Dashboard access</h3><p>Use <b>SMART_ROUTER_CLIENT_API_KEY</b>. The key stays in this browser tab's session storage and is never written by the dashboard.</p><div class="authrow"><input id="apiKey" type="password" autocomplete="off" placeholder="Paste client API key"><button class="primary" id="saveKey">Connect</button><button id="clearKey">Clear</button></div></div>

    <section class="hero">
      <div class="card routehero"><h2>Automatic request path</h2><p>Only <b>model=auto</b> enters automatic selection. Explicit upstream models pass through unchanged; tier aliases are optional overrides.</p><div class="flow"><span class="node auto">model=auto</span><span class="arrow">→</span><div class="tiers"><span class="tier">FAST</span><span class="tier">STANDARD</span><span class="tier">STRONG</span><span class="tier">CODING</span><span class="tier">VISION</span></div><span class="arrow">→</span><span class="node">upstream route</span></div></div>
      <div class="card quality"><div class="qtop"><div><div class="eyebrow">Measurement quality</div><div class="small muted">usage coverage</div></div><span class="statuspill" id="qualityBadge">waiting</span></div><div class="score" id="qualityScore">—</div><div class="small muted" id="qualityText">Waiting for telemetry.</div></div>
    </section>

    <section class="metrics">
      <div class="card metric accent"><div class="label">Routed requests</div><div class="value" id="requests">—</div><div class="sub" id="usageCoverage">Usage coverage —</div></div>
      <div class="card metric"><div class="label">Measured tokens</div><div class="value" id="tokens">—</div><div class="sub" id="tokenSplit">Input — · Output —</div></div>
      <div class="card metric"><div class="label">Measured cost</div><div class="value" id="cost">—</div><div class="sub" id="costCoverage">Pricing coverage —</div></div>
      <div class="card metric"><div class="label">Savings vs strong</div><div class="value" id="savings">—</div><div class="sub" id="savingsUsd">Same-token baseline</div></div>
      <div class="card metric"><div class="label">Strong-only baseline</div><div class="value" id="baseline">—</div><div class="sub">same-token strong-only baseline: measured token counts at strong-tier pricing.</div></div>
      <div class="card metric"><div class="label">Budget-cap reduction</div><div class="value" id="budget">—</div><div class="sub">Enforced output-cap delta; not claimed as generated-token savings.</div></div>
      <div class="card metric"><div class="label">Streaming requests</div><div class="value" id="streaming">—</div><div class="sub">Upstream streaming usage can be incomplete.</div></div>
      <div class="card metric"><div class="label">Runtime</div><div class="value">v<span id="version" class="ver"></span></div><div class="sub">Hermes Smart Router Flight Deck.</div></div>
    </section>

    <section class="lower">
      <div class="card panel"><div class="panelhead"><h3>Route mix</h3><span class="small muted">automatic tier decisions</span></div><div id="tiers"></div><div class="zero" id="zeroState"><b>No routed requests in this window.</b><br>Send a request with <code>model=auto</code> through Hermes/OpenWebUI, then refresh. Explicit model selections intentionally do not increment automatic tier routing.</div></div>
      <div class="card panel"><div class="panelhead"><h3>Measurement notes</h3><span class="small muted" id="lastUpdated">not refreshed yet</span></div><div id="notice" class="notice">Loading telemetry…</div><div class="legend" id="meta"></div></div>
    </section>
    <section class="card panel" style="margin-top:12px"><div class="panelhead"><h3>Request traces</h3><span class="small muted">auth → guardrails → RAG → routing → fallback → result</span></div><div id="traces" class="trace-list"><div class="muted">Loading traces…</div></div><div id="traceDetail" class="code" style="display:none"></div></section>
  </main>
</div>
<script>
const VERSION=__HERMES_VERSION_JSON__;document.querySelectorAll('.ver').forEach(x=>x.textContent=VERSION);function applyTheme(v){const t=v||localStorage.getItem('hermes_theme')||'dark';document.documentElement.dataset.theme=t;localStorage.setItem('hermes_theme',t);$('theme')&&($('theme').textContent=t==='dark'?'☀ Light':'☾ Dark')}function toggleTheme(){applyTheme((document.documentElement.dataset.theme||'dark')==='dark'?'light':'dark')}
const $=id=>document.getElementById(id);const fmtInt=n=>new Intl.NumberFormat().format(Number(n||0));const fmtUsd=n=>'$'+Number(n||0).toFixed(Number(n||0)<1?4:2);const fmtPct=n=>n==null?'N/A':(Number(n)*100).toFixed(1)+'%';
let timer=null;function key(){return sessionStorage.getItem('hermesDashboardKey')||''}function setAuth(ok,msg){$('authState').textContent=msg;$('authDot').style.background=ok?'var(--green)':'var(--amber)'}
async function load(){const headers=key()?{'Authorization':'Bearer '+key()}:{};const r=await fetch('/dashboard/api/summary?hours='+encodeURIComponent($('hours').value),{cache:'no-store',headers});if(!r.ok){setAuth(false,r.status===401?'Access key required':'API error '+r.status);throw new Error(r.status===401?'API key required or invalid':'dashboard API returned '+r.status)}const d=await r.json();setAuth(true,'Connected');$('requests').textContent=fmtInt(d.requests);$('usageCoverage').textContent='Usage coverage '+fmtPct(d.usage_coverage);$('tokens').textContent=fmtInt(d.total_tokens);$('tokenSplit').textContent='Input '+fmtInt(d.input_tokens)+' · Output '+fmtInt(d.output_tokens);$('cost').textContent=d.priced_requests?fmtUsd(d.actual_cost_usd):'N/A';$('costCoverage').textContent='Pricing coverage '+fmtPct(d.cost_coverage);$('savings').textContent=d.savings_pct==null?'N/A':fmtPct(d.savings_pct);$('savingsUsd').textContent=d.priced_requests?fmtUsd(d.savings_usd)+' measured saving':'Configure tier pricing to calculate USD';$('baseline').textContent=d.priced_requests?fmtUsd(d.strong_same_token_cost_usd):'N/A';$('budget').textContent=fmtInt(d.budget_tokens_avoided);$('streaming').textContent=fmtInt(d.streaming_requests);const total=Math.max(1,Object.values(d.tier_counts||{}).reduce((a,b)=>a+Number(b),0));$('tiers').innerHTML=['fast','standard','strong'].map(t=>{const n=Number((d.tier_counts||{})[t]||0),p=n/total*100;return `<div class="barrow"><div>${t}</div><div class="track"><div class="fill" style="width:${p.toFixed(2)}%"></div></div><div>${n} · ${p.toFixed(0)}%</div></div>`}).join('');$('zeroState').classList.toggle('show',!d.requests);const warnings=[];if(d.error)warnings.push('Cost ledger: '+d.error);if(!d.pricing_configured)warnings.push('Tier USD pricing is not fully configured, so cost/savings values are intentionally unavailable.');if(d.requests&&d.usage_coverage<.95)warnings.push('Usage coverage is below 95%; treat displayed cost as partial.');if(!warnings.length)warnings.push('Measurement coverage is healthy for this window. USD values use measured upstream usage only.');$('notice').textContent=warnings.join(' ');$('notice').className=(d.error||!d.pricing_configured||(d.requests&&d.usage_coverage<.95))?'notice warn':'notice';const q=d.requests?Number(d.usage_coverage||0):0;$('qualityScore').textContent=d.requests?fmtPct(q):'No data';$('qualityText').textContent=d.requests?(q>=.95?'Healthy measured usage coverage.':'Coverage needs attention before cost conclusions.'):'Generate model=auto traffic to begin measurement.';$('qualityBadge').textContent=!d.requests?'idle':q>=.95?'healthy':'partial';$('qualityBadge').style.color=!d.requests?'var(--muted)':q>=.95?'var(--green)':'var(--amber)';$('meta').innerHTML=`<span>Baseline <b>${d.cost_baseline}</b></span><span>Pricing <b>${d.pricing_source||'not configured'}</b></span>`;$('lastUpdated').textContent='updated '+new Date().toLocaleTimeString();document.querySelector('.main').classList.remove('flash');void document.querySelector('.main').offsetWidth;document.querySelector('.main').classList.add('flash');loadTraces().catch(()=>{})}
async function loadTraces(){const headers=key()?{'Authorization':'Bearer '+key()}:{};const r=await fetch('/dashboard/api/traces?limit=120',{cache:'no-store',headers});if(!r.ok)return;const d=await r.json();const ids=[...new Set(d.map(x=>x.request_id))].slice(0,30);$('traces').innerHTML=ids.map(id=>{const rows=d.filter(x=>x.request_id===id),last=rows[0]||{},result=rows.find(x=>x.stage==='result');return `<div class="trace-row" data-id="${id}"><div class="trace-stage">${id}</div><div class="small muted">${last.ts||''} · ${rows.length} steps · ${result?.status||'in progress'}</div></div>`}).join('')||'<div class="muted">No traces yet.</div>';document.querySelectorAll('.trace-row').forEach(x=>x.onclick=()=>openTrace(x.dataset.id))}async function openTrace(id){const headers=key()?{'Authorization':'Bearer '+key()}:{};const r=await fetch('/dashboard/api/traces/'+encodeURIComponent(id),{cache:'no-store',headers});if(!r.ok)return;const d=await r.json();const el=$('traceDetail');el.style.display='block';el.textContent=d.map(x=>`${x.seq}. ${x.stage} [${x.status}]\n${JSON.stringify(x.detail,null,2)}`).join('\n\n')}
function showError(e){$('notice').textContent=String(e);$('notice').className='notice warn'}function schedule(){if(timer)clearInterval(timer);const s=Number($('autoRefresh').value);if(s)timer=setInterval(()=>load().catch(()=>{}),s*1000)}
applyTheme();$('theme').onclick=toggleTheme;$('authBtn').onclick=()=>$('authBox').classList.toggle('open');$('saveKey').onclick=()=>{sessionStorage.setItem('hermesDashboardKey',$('apiKey').value.trim());$('authBox').classList.remove('open');load().catch(showError)};$('clearKey').onclick=()=>{sessionStorage.removeItem('hermesDashboardKey');$('apiKey').value='';setAuth(false,'Key cleared');load().catch(showError)};$('apiKey').value=key();$('refresh').onclick=()=>load().catch(showError);$('hours').onchange=()=>load().catch(showError);$('autoRefresh').onchange=schedule;schedule();load().catch(showError);
</script>
</body></html>'''
